property_tests.invariant_check:
from agentfox.core.models import resolve_model, TIER_DEFAULTS
for tier in ['SIMPLE', 'STANDARD', 'ADVANCED']:
    assert resolve_model(tier, variant=None) == TIER_DEFAULTS[tier]

from agentfox.core.models import resolve_model
for tier in ['SIMPLE', 'STANDARD', 'ADVANCED']:
    for variant in ['fast', 'standard', 'extended', 'turbo', 'UNKNOWN_VARIANT', 'x'*100]:
        try:
            result = resolve_model(tier, variant=variant)
            assert isinstance(result, str) and len(result) > 0
        except Exception as e:
            assert False, f'resolve_model raised {type(e).__name__}: {e}'

for starting_variant in [None, 'fast', 'standard', 'extended']:
    ladder = EscalationLadder(..., starting_variant=starting_variant)
    initial = ladder.current_variant
    for _ in range(3):
        if ladder.can_escalate():
            ladder.escalate()
        assert ladder.current_variant == initial, f'current_variant changed from {initial} to {ladder.current_variant}'

for mode_variant in ['fast', 'standard', 'extended']:
    for arch_variant in ['fast', 'standard', 'extended']:
        archetype = ArchetypeEntry(..., default_model_variant=arch_variant)
        mode = ModeConfig(..., model_variant=mode_variant)
        result = resolve_effective_config(archetype, mode)
        assert result.default_model_variant == mode_variant

